const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || message.text || payload.text || '').trim();
const limit = Number(source.limit || payload.limit || 10) || 10;
const folderId = source.folderId || payload.folderId || '';
return [{ json: { ...source, payload, message, chatId, raw, limit, folderId } }];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');
const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};
const formatDate = (value) => {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

const source = $('Chuan Bi List Files').item.json;
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
let text = '📁 <b>File gan day trong Google Drive</b>

';
if (!rows.length) {
  text += 'Khong tim thay file nao.';
} else {
  rows.forEach((file, index) => {
    const link = pickFirst(file.webViewLink);
    text += String(index + 1) + '. ';
    text += link ? '<a href="' + escapeHtml(link) + '">' + escapeHtml(file.name || 'Khong ro ten') + '</a>' : '<b>' + escapeHtml(file.name || 'Khong ro ten') + '</b>';
    text += '
ID: ' + escapeHtml(file.id || '') + '
';
    text += 'Loai: ' + escapeHtml(file.mimeType || 'Khong ro') + '
';
    const modified = formatDate(file.modifiedTime);
    if (modified) text += 'Sua luc: ' + escapeHtml(modified) + '
';
    text += '
';
  });
}
return [{ json: { chatId: source.chatId, text: text.trim() } }];
